entities.sql:
SELECT bank_id, max(bank_name) AS bank_name FROM (
  SELECT bank_id, bank_name FROM {silver_aml.account}
  UNION ALL SELECT from_bank, CAST(NULL AS string) FROM {silver_aml.transfer}
  UNION ALL SELECT to_bank, CAST(NULL AS string) FROM {silver_aml.transfer}) b
WHERE bank_id IS NOT NULL
GROUP BY bank_id

edges.sql:
WITH ep AS (
  SELECT from_bank AS b, from_account AS a FROM {silver_aml.transfer}
  UNION SELECT to_bank, to_account FROM {silver_aml.transfer}
  UNION SELECT bank_id, account_number FROM {silver_aml.account})
SELECT b, a FROM ep WHERE b IS NOT NULL AND a IS NOT NULL

edges.expect_rows:
SELECT count(*) FROM (
  SELECT DISTINCT attempt_id, from_bank, from_account FROM {silver_aml.laundering_attempt}
  WHERE from_bank IS NOT NULL AND from_account IS NOT NULL
  UNION
  SELECT DISTINCT attempt_id, to_bank, to_account FROM {silver_aml.laundering_attempt}
  WHERE to_bank IS NOT NULL AND to_account IS NOT NULL)

